text:
      if (line.startsWith("..")) {
        // Remove stuffed dot.
        line = line.slice(1);
      }
      lineCallback(line);
      this._data = this._data.slice(index + 2);
      if (++i % 1000 == 0) {
        // Prevent blocking main process for too long.
        await new Promise(resolve => setTimeout(resolve));
      }
    }
    // Note: _data will be empty and receivingMultiLineResponse will be false
    // at this point.
    doneCallback();
